import React, { useState } from "react";
import data from "../sentence.json";
import Swal from "sweetalert2";
import "animate.css";
import { useNavigate } from "react-router-dom";
import { DragDropContainer, DropTarget } from "react-drag-drop-container";
import { Button, FormControl, MenuItem, Select, Slider } from "@mui/material";

const Level2MidContent = () => {
  let navigate = useNavigate();
  let [randomNumber, setRandomNumber] = useState(0);
  let [randomnoArray, setRandomNoArray] = useState([0]);
  let [isDisableNext, setIsDisableNext] = useState(true);
  let [skipCount, setSkipCount] = useState(0);
  let [formedSentenceArray, setFormedSentenceArray] = useState([]);
  let [level, setLevel] = useState("Level 2");

  function shuffleArray(array) {
    for (let i = array.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1));
      [array[i], array[j]] = [array[j], array[i]];
    }
    return array;
  }

  const handleNext = () => {
    setFormedSentenceArray([]);
    setIsDisableNext(true);
    if (randomnoArray.length != 10) {
      let randomNo = Math.floor(Math.random() * data.level2.length);
      if (randomnoArray.includes(randomNo)) {
        handleNext();
      } else {
        setRandomNumber(randomNo);
        randomnoArray.push(randomNo);
      }
    } else {
      Swal.fire({
        title: `You have successfully completed ${
          10 - skipCount
        } out of 10 sentences!`,
        showClass: {
          popup: "animate__animated animate__fadeInDown",
        },
        hideClass: {
          popup: "animate__animated animate__fadeOutUp",
        },
        customClass: {
          title: "completeion-text",
          htmlContainer: "completeion-text",
        },
        confirmButtonText: "Restart",
      }).then((result) => {
        if (result.isConfirmed) {
          setRandomNoArray([0]);
          navigate("/");
        }
      });
    }

    //code to clean up the boxes when click on next/skip
    let arr = data.level2[randomNumber].sentence.split(" ");
    for (let i = 0; i < arr.length; i++) {
      document.getElementById(`drop_${i}`).innerHTML = null;
    }
  };

  const handleChange = (event) => {
    switch (event.target.value) {
      case "Level 1":
        navigate("/launchpage/englishactivity/level1");
        break;
      case "Level 2":
        navigate("/launchpage/englishactivity/level2");
        break;
    }
  };

  const handleVerify = () => {
    let sentence = data.level2[randomNumber].sentence;
    let formedSentence = formedSentenceArray.join(" ");
    console.log("sentence", sentence);
    console.log("formed sentence", formedSentence);

    if (formedSentence) {
      if (sentence == formedSentence) {
        setIsDisableNext(false);
        Swal.fire({
          title: "Correct!",
          text: `"${formedSentence}" is the right sentence.`,
          customClass: {
            title: "green-text",
            htmlContainer: "green-text",
          },
        });
      } else {
        Swal.fire({
          title: "Incorrect!",
          text: `"${formedSentence}" is not the right sentence.`,
          customClass: {
            title: "red-text",
            htmlContainer: "red-text",
          },
        });
      }
    } else {
      Swal.fire({
        title: "Oops!",
        text: "Please fill all the blank boxes by dragging and dropping the words!",
        customClass: {
          title: "red-text",
          htmlContainer: "red-text",
        },
      });
    }
  };

  const handleSkip = () => {
    let newCount = skipCount + 1;
    setSkipCount(newCount);
    handleNext();
  };

  const handleDrop = (e, index) => {
    const newWord = e.dragData.word;
    const updatedArray = [...formedSentenceArray]; // Copy the current array
    updatedArray[index] = newWord; // Replace the word at the specified index with the new word
    setFormedSentenceArray(updatedArray); // Update the state with the updated array

    console.log(`${newWord} will be dropped at index ${index}`);
    document.getElementById(`drop_${index}`).innerHTML = newWord;
  };
  return (
    <div
      className="row d-flex scrollbar-primary"
      style={{
        width: "100vw",
        backgroundColor: "#F2FBFF",
        borderRadius: "14px",
        opacity: 1,
        boxShadow: "0px 10px 5px rgba(0, 0, 0, 0.40)",
        display: "block",
        overflow: "auto",
      }}
    >
      <div className="col-sm-9 d-flex align-items-center justify-content-center">
        <div
          className="scrollbar-primary"
          style={{
            height: "80vh",
            width: "95%",
            background: "#FFFFFF 0% 0% no-repeat padding-box",
            borderRadius: "13px",
            boxShadow: "0px 4px 7px #00000029",
            display: "block",
            padding: "4%",
            paddingTop: "0%",
            overflow: "auto",
            overflowX: "hidden",
            margin: "5px",
          }}
        >
          <div className="row mb-3 sticky-top">
            <div className="d-flex justify-content-end">
              <FormControl size="small">
                <Select
                  labelId="demo-simple-select-label"
                  id="demo-simple-select"
                  value={level}
                  onChange={handleChange}
                  sx={{
                    bgcolor: "green",
                    borderRadius: "8px",
                    "& .MuiOutlinedInput-notchedOutline": {
                      borderColor: "green",
                    },
                    color: "white",
                  }}
                >
                  <MenuItem value="Level 1">Level 1</MenuItem>
                  <MenuItem value="Level 2">Level 2</MenuItem>
                </Select>
              </FormControl>
            </div>
          </div>
          <div className="row mb-3">
            <div className="d-flex align-items-center">
              <span className="me-3">Sentence</span>

              <Slider
                defaultValue={1}
                step={1}
                min={0}
                max={10}
                value={randomnoArray.length}
                color="success"
                marks
                valueLabelDisplay="on"
                sx={{
                  "& .MuiSlider-mark": {
                    width: 12,
                    height: 12,
                    borderRadius: "50%",
                  },
                }}
              />

              <span
                className="ms-3"
                style={{
                  height: "40px",
                  width: "45px",
                  borderRadius: "50%",
                  backgroundColor: "lightblue",

                  display: "flex",
                  justifyContent: "center",
                  alignItems: "center",
                }}
              >
                {randomnoArray.length}/{10}
              </span>
            </div>
          </div>
          <div className="row mb-2">
            <div
              className="scrollbar-primary"
              style={{
                background:
                  "transparent linear-gradient(268deg, #FDBD23 0%, #F7B94E 100%) 0% 0% no-repeat padding-box",
                borderRadius: "25px",
                opacity: "1",
                color: "black",
                padding: "2%",
                margin: "0%",
                overflowX: "auto",
              }}
            >
              <div className="d-flex">
                {data.level2[randomNumber].sentence
                  .split(" ")
                  .map((item, index) => (
                    <DropTarget
                      targetKey="item"
                      onHit={(e) => handleDrop(e, index)}
                    >
                      <div className="col">
                        <div key={index} className="item-card">
                          <p id={`drop_${index}`}></p>
                        </div>
                      </div>
                    </DropTarget>
                  ))}
              </div>
            </div>
          </div>
          <div className="row mb-5">
            <div
              style={{
                background:
                  "transparent linear-gradient(268deg, #FDBD23 0%, #F7B94E 100%) 0% 0% no-repeat padding-box",
                borderRadius: "25px",
                opacity: "1",
                color: "black",
                padding: "2%",
                margin: "0%",
              }}
            >
              <div className="col d-flex justify-content-center align-items-center">
                <div className="row row-cols-1 row-cols-md-2 row-cols-lg-5 g-1  d-flex justify-content-around w-100">
                  <div className="bg-warning d-flex flex-column align-items-center justify-content-center border rounded-4 p-3">
                    {data.level2[randomNumber].words.subject.map(
                      (item, index) => (
                        <DragDropContainer
                          key={index}
                          targetKey="item"
                          dragData={{ word: item }}
                        >
                          <div key={index} className="col">
                            <div className="item-card">
                              <p id="item">{item}</p>
                            </div>
                          </div>
                        </DragDropContainer>
                      )
                    )}
                  </div>
                  <div className="bg-warning d-flex flex-column align-items-center justify-content-center border rounded-4 p-3">
                    {data.level2[randomNumber].words.verb.map((item, index) => (
                      <DragDropContainer
                        key={index}
                        targetKey="item"
                        dragData={{ word: item }}
                      >
                        <div key={index} className="col">
                          <div className="item-card">
                            <p id="item">{item}</p>
                          </div>
                        </div>
                      </DragDropContainer>
                    ))}
                  </div>
                  <div className="bg-warning d-flex flex-column align-items-center justify-content-center border rounded-4 p-3">
                    {data.level2[randomNumber].words.object.map(
                      (item, index) => (
                        <DragDropContainer
                          key={index}
                          targetKey="item"
                          dragData={{ word: item }}
                        >
                          <div key={index} className="col">
                            <div className="item-card">
                              <p id="item">{item}</p>
                            </div>
                          </div>
                        </DragDropContainer>
                      )
                    )}
                  </div>
                  <div className="bg-warning d-flex flex-column align-items-center justify-content-center border rounded-4 p-3">
                    {data.level2[randomNumber].words.other.map(
                      (item, index) => (
                        <DragDropContainer
                          key={index}
                          targetKey="item"
                          dragData={{ word: item }}
                        >
                          <div key={index} className="col">
                            <div className="item-card">
                              <p id="item">{item}</p>
                            </div>
                          </div>
                        </DragDropContainer>
                      )
                    )}
                  </div>
                </div>
              </div>
            </div>
          </div>
          <div className="row mb-2">
            <div className="d-flex justify-content-around">
              <Button variant="contained" onClick={handleSkip}>
                Skip
              </Button>
              <Button
                variant="contained"
                color="success"
                onClick={handleVerify}
              >
                Verify
              </Button>
              <Button
                disabled={isDisableNext}
                variant="contained"
                onClick={handleNext}
              >
                {randomnoArray.length == 10 ? "FINISH" : "NEXT"}
              </Button>
            </div>
          </div>
        </div>
      </div>
      <div className="col-sm-3 d-flex align-items-center justify-content-center">
        <div
          className="scrollbar-primary"
          style={{
            height: "80vh",
            width: "95%",
            overflow: "auto",
            overflowX: "hidden",
            borderRadius: "13px",
            boxShadow: "0px 4px 7px #00000029",
            display: "block",
            background: "#FFFFFF 0% 0% no-repeat padding-box",
            margin: "5px",
          }}
        >
          <div
            className="sticky-top text-center subheading"
            style={{
              background: "#002F65",
              borderRadius: "13px 13px 0px 0px",
              opacity: "1",
              color: "#FFFFFF",
              fontSize: "calc(1rem + 0.2vw)",
              fontWeight: "bolder",
            }}
          >
            Instructions
          </div>
          <div style={{ maxHeight: "50vh", padding: "2%", lineHeight: "30px" }}>
            <ul>
              <li>
                Drag the word from the list of words and drop into the blank
                cells.
              </li>
              <li>
                After filling all the blank cells click on the "VERIFY" button.
              </li>
              <li>
                Click on the "NEXT" button to get the next list of words to
                create another sentence.
              </li>
            </ul>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Level2MidContent;
