import React, { useEffect, useState } from "react";
import InfoPopUpForDetailView from "./InfoPopUpForDetailView";
import ViewDetailsPopup from "./ViewDetailsPopup";
import data from "../sentence.json";
import Swal from "sweetalert2";
import { DragDropContext, Droppable, Draggable } from "react-beautiful-dnd";
import "animate.css";
import { useNavigate } from "react-router-dom";
import { Button, FormControl, MenuItem, Select, Slider } from "@mui/material";

const Level1MidContent = () => {
  const navigate = useNavigate();
  const [sentence, setSentence] = useState("");
  //let [buildSentence, setBuildSentence] = useState("");
  const [shuffledArray, setShuffledArray] = useState([]);
  let [showDialogue, setShowDialogue] = useState(false);
  // let [flag, setFlag] = useState(false);
  let [count, setCount] = useState(0);
  let [randomnoArray, setRandomNoArray] = useState([]);
  // let [disableVerify, setDisableVerify] = useState(false);
  let [disableNext, setDisableNext] = useState(true);
  let [PreviousArray, setPreviousArray] = useState([]);
  let [sentences, setSentences] = useState([]);
  let [randomIndex, setrandomIndex] = useState();
  let [skipCount, setSkipCount] = useState(0);
  let [level, setLevel] = useState("Level 1");

  useEffect(() => {
    data.level1.map((item) => {
      sentences.push(item.sentence);
    });
    const randomIndex = Math.floor(Math.random() * data.level1.length);
    randomnoArray.push(randomIndex);
    setrandomIndex(randomIndex);
    const randomSentence = data.level1[randomIndex].sentence;
    setSentence(randomSentence);
  }, []);

  useEffect(() => {
    const wordsArray = sentence.split(" ");
    const shuffledWordsArray = shuffleArray(wordsArray);
    setShuffledArray(shuffledWordsArray);
    //buildSentence = shuffledArray.join(" ");
  }, [sentence]);

  function shuffleArray(array) {
    for (let i = array.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1));
      [array[i], array[j]] = [array[j], array[i]];
    }
    return array;
  }

  const handleNext = () => {
    setDisableNext(true);
    if (randomnoArray.length != 10) {
      let randomNo = Math.floor(Math.random() * data.level1.length);
      if (randomnoArray.includes(randomNo)) {
        handleNext();
      } else {
        randomnoArray.push(randomNo);
        setSentence(sentences[randomNo]);
        setrandomIndex(randomNo);
      }
    } else {
      Swal.fire({
        title: `You have successfully completed ${
          10 - skipCount
        } out of 10 sentences!`,
        showClass: {
          popup: "animate__animated animate__fadeInDown",
        },
        hideClass: {
          popup: "animate__animated animate__fadeOutUp",
        },
        customClass: {
          title: "completeion-text",
          htmlContainer: "completeion-text",
        },
        confirmButtonText: "Proceed to Level-2",
      }).then((result) => {
        if (result.isConfirmed) {
          setRandomNoArray([]);
          navigate("/launchpage/englishactivity/level2");
        }
      });
    }
  };

  const handleVerify = () => {
    let sen = shuffledArray.join(" ");
    if (sentences.includes(sen)) {
      // Swal.fire("Good job!", `"${sen}." is the right sentence.`, "success");
      Swal.fire({
        title: "Good job!",
        text: `"${sen}." is the right sentence.`,
        customClass: {
          title: "green-text",
          htmlContainer: "green-text",
        },
      });
      setCount(0);
      const updatedArray = [...PreviousArray, sen];
      setPreviousArray(updatedArray);
      setDisableNext(false);
    } else {
      count = count + 1;
      setCount(count);
      let sen = shuffledArray.join(" ");
      GetPosition(sen);
    }
  };

  const onAgree = () => {
    setShowDialogue(false);
  };

  const handleHint = () => {
    setShowDialogue(true);
  };

  const handleSkip = () => {
    let newCount = skipCount + 1;
    setSkipCount(newCount);
    handleNext();
  };

  const GetPosition = (builtsent) => {
    let index = sentences.indexOf(sentence);

    let subpos = 0;
    let verbpos = 0;
    let objpos = 0;

    let subject = "";
    let verb = "";
    let object = "";

    subject = data.level1[index].subject;
    verb = data.level1[index].verb;
    object = data.level1[index].object.split(" ")[0];

    subpos = builtsent.indexOf(subject);
    verbpos = builtsent.indexOf(verb);
    objpos = builtsent.indexOf(object);
    if (subpos > verbpos || subpos > objpos) {
      Swal.fire({
        title: "Incorrect!",
        text: `"${subject}" should be at the start of the sentence as it is subject.`,
        customClass: {
          title: "red-text",
          htmlContainer: "red-text",
        },
      });
    } else {
      if (verbpos > objpos || verbpos < subpos) {
        Swal.fire({
          title: "Incorrect!",
          text: `"${verb}" should be just after the subject as it is verb.`,
          customClass: {
            title: "red-text",
            htmlContainer: "red-text",
          },
        });
      } else {
        if (objpos < subpos || objpos < verbpos) {
          Swal.fire({
            title: "Incorrect!",
            text: `"${object}" should be at the last of the sentence as it is object.`,
            customClass: {
              title: "red-text",
              htmlContainer: "red-text",
            },
          });
        } else {
          // Swal.fire(
          //   "Wrong!",
          //   "Please try to rearranging the words in order to form a meaningful sentence."
          // );
          Swal.fire({
            title: "Incorrect!",
            text: "Please try to rearranging the words in order to form a meaningful sentence.",
            customClass: {
              title: "red-text",
              htmlContainer: "red-text",
            },
          });
        }
      }
    }
  };

  const onDragComplete = (result) => {
    if (!result.destination) return;
    const arr = [...shuffledArray];
    let removedItem = arr.splice(result.source.index, 1)[0];
    arr.splice(result.destination.index, 0, removedItem);
    // Updating the list
    setShuffledArray(arr);
  };

  const handleChange = (event) => {
    switch (event.target.value) {
      case "Level 1":
        navigate("/launchpage/englishactivity/level1");
        break;
      case "Level 2":
        navigate("/launchpage/englishactivity/level2");
        break;
    }
  };

  return (
    <div
      className="row d-flex scrollbar-primary"
      style={{
        width: "100vw",
        backgroundColor: "#F2FBFF",
        borderRadius: "14px",
        opacity: 1,
        boxShadow: "0px 10px 5px rgba(0, 0, 0, 0.40)",
        display: "block",
        overflow: "auto",
      }}
    >
      <div className="col-sm-9 d-flex align-items-center justify-content-center">
        <div
          className="scrollbar-primary"
          style={{
            height: "80vh",
            width: "95%",
            background: "#FFFFFF 0% 0% no-repeat padding-box",
            borderRadius: "13px",
            boxShadow: "0px 4px 7px #00000029",
            display: "block",
            padding: "4%",
            paddingTop: "0%",
            overflow: "auto",
            overflowX: "hidden",
            margin: "5px",
          }}
        >
          <div className="row mb-5 sticky-top">
            <div className="d-flex justify-content-between">
              <Button
                size="small"
                onClick={handleHint}
                variant="contained"
                color="success"
              >
                hint
              </Button>

              {/* <select onChange={handleChange} style={{ cursor: "pointer" }}>
                  <option selected value="level1">
                    Level 1
                  </option>
                  <option value="level2">Level 2</option>
                </select> */}
              <FormControl size="small">
                <Select
                  labelId="demo-simple-select-label"
                  id="demo-simple-select"
                  value={level}
                  onChange={handleChange}
                  sx={{
                    bgcolor: "green",
                    borderRadius: "8px",
                    "& .MuiOutlinedInput-notchedOutline": {
                      borderColor: "green",
                    },
                    color: "white",
                  }}
                >
                  <MenuItem value="Level 1">Level 1</MenuItem>
                  <MenuItem value="Level 2">Level 2</MenuItem>
                </Select>
              </FormControl>
            </div>
          </div>

          <div className="row mb-5">
            <div className="d-flex align-items-center">
              <span className="me-3">Sentence</span>

              <Slider
                defaultValue={1}
                step={1}
                min={0}
                max={10}
                value={randomnoArray.length}
                color="success"
                marks
                valueLabelDisplay="on"
                sx={{
                  "& .MuiSlider-mark": {
                    width: 12,
                    height: 12,
                    borderRadius: "50%",
                  },
                }}
              />

              <span
                className="ms-3"
                style={{
                  height: "40px",
                  width: "45px",
                  borderRadius: "50%",
                  backgroundColor: "lightblue",
                  display: "flex",
                  justifyContent: "center",
                  alignItems: "center",
                }}
              >
                {randomnoArray.length}/10
              </span>
            </div>
          </div>

          <div
            className="row mb-5"
            style={{
              background:
                "transparent linear-gradient(268deg, #FDBD23 0%, #F7B94E 100%) 0% 0% no-repeat padding-box",
              borderRadius: "25px",
              opacity: "1",
              color: "black",
              padding: "2%",
              margin: "0%",
            }}
          >
            <DragDropContext onDragEnd={onDragComplete}>
              <Droppable droppableId="characters" direction="horizontal">
                {(provided) => (
                  <div
                    className="col d-flex justify-content-center align-items-center"
                    {...provided.droppableProps}
                    ref={provided.innerRef}
                  >
                    {shuffledArray.map((item, index) => (
                      <Draggable
                        key={index}
                        draggableId={"" + index}
                        index={index}
                      >
                        {(provided) => (
                          <div
                            className="item-card"
                            ref={provided.innerRef}
                            {...provided.draggableProps}
                            {...provided.dragHandleProps}
                          >
                            <p id="item">{item} </p>
                          </div>
                        )}
                      </Draggable>
                    ))}
                    {provided.placeholder}
                  </div>
                )}
              </Droppable>
            </DragDropContext>
          </div>
          <div className="row mb-3">
            <div className="d-flex justify-content-around">
              <Button variant="contained" onClick={handleSkip}>
                Skip
              </Button>
              <Button
                variant="contained"
                onClick={handleVerify}
                color="success"
              >
                Verify
              </Button>
              <Button
                variant="contained"
                onClick={handleNext}
                disabled={disableNext}
              >
                {randomnoArray.length == 10 ? "FINISH" : "NEXT"}
              </Button>
            </div>
          </div>
        </div>
      </div>
      <div className="col-sm-3 d-flex align-items-center justify-content-center">
        <div
          className="scrollbar-primary"
          style={{
            height: "80vh",
            width: "95%",
            overflow: "auto",
            overflowX: "hidden",
            borderRadius: "13px",
            boxShadow: "0px 4px 7px #00000029",
            display: "block",
            background: "#FFFFFF 0% 0% no-repeat padding-box",
            margin: "5px",
          }}
        >
          <div
            className="sticky-top text-center subheading"
            style={{
              background: "#002F65",
              borderRadius: "13px 13px 0px 0px",
              opacity: "1",
              color: "#FFFFFF",
              fontSize: "calc(1rem + 0.2vw)",
              fontWeight: "bolder",
            }}
          >
            Instructions
          </div>
          <div style={{ maxHeight: "50vh", padding: "2%", lineHeight: "30px" }}>
            <div>
              <ul>
                <li>
                  Arrange the words properly in order to create a meaningful
                  sentence.
                </li>

                <li>Click on the "VERIFY" button to check the sentence.</li>
                <li>
                  Click on the "NEXT" button to move to the next sentence.
                </li>
              </ul>
            </div>
          </div>
        </div>
      </div>

      <InfoPopUpForDetailView
        openDialog={showDialogue}
        onAgree={onAgree}
        content={
          <ViewDetailsPopup randomIndex={randomIndex} data={data.level1} />
        }
        popuptitle="Hint"
      />
    </div>
  );
};

export default Level1MidContent;
